public static int factorial(int num) {
    if (num == 0) {
        return 1;
    } else {
        return num * factorial(num - 1);   // recursive call
    }
}

public static int power(int base, int exp) {
    if (exp == 0) {
        return 1;                        // base case
    }
    return base * power(base, exp - 1);  // general case
}

